using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class FetchDataTool
{
    private readonly IHttpClientFactory _httpClientFactory;

    public FetchDataTool(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool("fetch_data"), Description("Fetches data from an external API endpoint.")]
    public async Task<string> FetchDataAsync(
        [Description("The relative path to fetch (e.g. /users/1)")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();
        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt to summarize the given text.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Optional target length (e.g. '2 sentences')")] string? length = null)
    {
        var instruction = length is not null
            ? $"Summarize the following text in approximately {length}:"
            : "Summarize the following text concisely:";

        return
        [
            new McpServerPromptMessage
            {
                Role = "user",
                Content = new McpServerPromptContent
                {
                    Type = "text",
                    Text = $"{instruction}\n\n{text}"
                }
            }
        ];
    }
}

